(()=>{
const hero=document.querySelector('.hero-actions');
hero.insertAdjacentHTML('afterend',`<aside class="advisor-intro" aria-label="你的企業轉型顧問"><div class="advisor-portrait"><img src="assets/fion-consultant.webp" alt="Fion，企業轉型顧問" width="160" height="180"></div><div class="advisor-copy"><span class="advisor-label">YOUR TRANSFORMATION PARTNER</span><h2>Fion <span>企業轉型顧問</span></h2><p>陪企業主，把策略變成成果。</p><a href="#contact">從你的經營難題開始 <span aria-hidden="true">↗</span></a></div></aside>`);
const items=[
{title:'活動花了錢，商機留不住？',tag:'EVENTS & FRANCHISE GROWTH',icon:'signal',pain:'活動辦完只剩照片，現場名單沒有變成下一步。',solution:'從活動策劃，到招商成交追蹤。',steps:['策略與預算','展前邀約與內容','現場洽談與分流','展後跟進與轉換'],notes:['對齊招商目標、目標客群與預算，排定人力、物料與執行時程。','規劃活動主題、招商話術與宣傳素材，串接報名及邀約追蹤。','設計現場動線與接待流程，依意向記錄需求、分級並派案。','設定跟進責任與節奏，以名單、洽談、成交及成本回看效益。'],deliver:'活動企劃・預算與執行表・招商轉換看板',metric:'有效名單／跟進率／加盟成交',need:'活動策劃與招商轉換'},
{title:'AI 做了，流程卻沒變？',tag:'AI ADOPTION',icon:'spark',pain:'PoC 做完、工具買了，團隊仍在手動搬資料。',solution:'選對試點，讓 AI 進入核心流程。',steps:['盤點重複工作','串接資料與規則','人工覆核例外','驗收並交接'],notes:['選高頻、可量測的工作，記錄現況工時與錯誤率。','建立輸入格式、處理規則與系統之間的交接。','標記異常並交由負責人核對，保留操作紀錄。','比對前後工時、正確率與使用率，完成團隊訓練。'],deliver:'試點流程圖・覆核機制・操作手冊',metric:'工時／錯誤率／採用率',need:'AI 工作流與系統'},
{title:'報表很多，決策還是慢？',tag:'DATA & DECISIONS',icon:'chart',pain:'部門各有一套數字，開會都在對帳。',solution:'統一指標，讓數字連到決策。',steps:['確認決策問題','定義共同口徑','整合戰情視圖','責任與行動追蹤'],notes:['先確認管理者需要做哪個決定，避免堆砌無用報表。','定義資料來源、更新頻率與指標計算方式。','將成本、進度、轉換與異常放在同一個介面。','異常對應負責人與期限，定期回看改善結果。'],deliver:'指標字典・資料對照表・決策儀表板',metric:'資料完整度／更新時效／結案率',need:'財務營運與戰情板'},
{title:'活動有名單，成交沒下文？',tag:'LEAD CONVERSION',icon:'signal',pain:'曝光、活動、業務各自作業，好名單逐漸冷掉。',solution:'打通來源到成交，讓預算有依據。',steps:['標記名單來源','分級與派案','設定跟進節奏','回看成交成本'],notes:['串接網站、內容與活動來源，避免名單失去脈絡。','依需求與互動訊號分流，指派跟進負責人。','設定回覆時限與提醒，記錄每次跟進及流失原因。','用詢問、到場、成交漏斗比較不同活動的投入。'],deliver:'來源追蹤・CRM 分流・活動效益看板',metric:'回覆時效／到場率／成交成本',need:'CRM 與會員經營'},
{title:'官網很好看，卻沒人詢問？',tag:'WEBSITE & GROWTH',icon:'target',pain:'流量來了就走，服務說不清，也找不到下一步。',solution:'把網站，做成能承接需求的入口。',steps:['釐清客群痛點','重整內容與入口','串接需求表單','追蹤詢問轉換'],notes:['對齊目標客群、搜尋意圖與購買疑慮。','規劃服務頁、信任證據與行動引導，兼顧行動版。','讓表單連到名單整理與跟進流程，保留必要同意。','設定事件與漏斗，驗證入口是否帶來有效詢問。'],deliver:'網站製作・SEO 架構・轉換追蹤',metric:'有效詢問／表單完成率／來源品質',need:'官網與互動網頁'},
{title:'新事業想投，風險看不清？',tag:'VENTURE VALIDATION',icon:'target',pain:'只有亮點與樂觀預估，沒有查核與退出條件。',solution:'先驗證假設，再決定資源投入。',steps:['研究市場需求','查核關鍵假設','試算風險情境','決定試點門檻'],notes:['比較客群、競品、替代方案與付費意願。','建立資料來源、紅旗與待確認清單，區分事實和假設。','拆解收入、成本與資金需求，進行敏感度分析。','定義啟動預算、里程碑與停損條件，再投入試點。'],deliver:'市場研究・盡調清單・情境試算',metric:'損益兩平點／資金缺口／試點門檻',need:'新事業盡職調查'},
{title:'規模變大，什麼都卡在老闆？',tag:'SCALABLE OPERATIONS',icon:'people',pain:'門市、團隊各做各的，關鍵工作沒有人接得住。',solution:'把個人經驗，變成組織的執行能力。',steps:['拆解關鍵流程','定義權責與標準','建立訓練機制','追蹤現場執行'],notes:['找出容易延誤、重工與依賴特定人的環節。','定義責任分工、交付標準、核准權限與例外處理。','將流程整理成可示範、可練習、可交接的教材。','用週期追蹤與回饋，修正各據點或部門的落差。'],deliver:'權責矩陣・SOP・門市營運追蹤',metric:'交接完成率／執行一致性／處理時效',need:'組織與連鎖營運'}
];
const icon=id=>`<svg class="icon" aria-hidden="true"><use href="#ic-${id}"/></svg>`;
const hub=document.createElement('section');hub.className='advisory-hub';hub.innerHTML=`<div class="advisory-heading"><div><span class="advisor-label">MORE BUSINESS BOTTLENECKS</span><h2>下一個瓶頸，也有解法。</h2></div><span>選痛點 → 看流程 → 定義成果</span></div><div class="advisory-picker" role="tablist" aria-label="更多企業痛點">${items.map((x,i)=>`<button type="button" role="tab" id="bottleneck-${i}" aria-controls="advisory-detail" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-bottleneck="${i}">${icon(x.icon)}<span>${x.title}</span></button>`).join('')}</div><div id="advisory-detail" class="advisory-detail" role="tabpanel" aria-labelledby="bottleneck-0"></div>`;
document.querySelector('#solutions>.wrap').append(hub);
let current=0,at=0,timer;
function stop(){clearTimeout(timer);timer=null;hub.querySelector('.advisory-play')?.setAttribute('aria-pressed','false');const b=hub.querySelector('.advisory-play');if(b)b.textContent='播放流程';}
function stage(n){at=n;const x=items[current];hub.querySelectorAll('[data-advisory-step]').forEach((b,i)=>{b.setAttribute('aria-pressed',String(i===n));b.classList.toggle('complete',i<n)});hub.querySelector('.advisory-stage-note').textContent=x.notes[n];}
function render(n){stop();current=n;const x=items[n];hub.querySelectorAll('[data-bottleneck]').forEach((b,i)=>{b.setAttribute('aria-selected',String(i===n));b.tabIndex=i===n?0:-1});const p=hub.querySelector('#advisory-detail');p.setAttribute('aria-labelledby','bottleneck-'+n);p.innerHTML=`<div class="advisory-problem"><span>${x.tag}</span><p>${x.pain}</p></div><div class="advisory-answer"><h3>${x.solution}</h3><button class="advisory-play" type="button" aria-pressed="false">播放流程</button></div><div class="advisory-flow" aria-label="改善流程">${x.steps.map((t,i)=>`<button type="button" data-advisory-step="${i}" aria-pressed="${i===0}"><span class="advisory-step-number">0${i+1}</span>${icon(['target','flow','people','chart'][i])}<b>${t}</b><small>${['DEFINE','CONNECT','VALIDATE','EXECUTE'][i]}</small></button>${i<3?'<span class="advisory-connector" aria-hidden="true"><i></i>→</span>':''}`).join('')}</div><p class="advisory-stage-note" aria-live="polite">${x.notes[0]}</p><div class="advisory-delivery"><div><small>交付成果</small><strong>${x.deliver}</strong></div><div><small>驗收指標</small><strong>${x.metric}</strong></div><a href="#contact">討論這個問題 ↗</a></div>`;
p.querySelectorAll('[data-advisory-step]').forEach(b=>b.onclick=()=>{stop();stage(+b.dataset.advisoryStep)});p.querySelector('.advisory-play').onclick=()=>{if(timer){stop();return}stage(0);let b=p.querySelector('.advisory-play');b.setAttribute('aria-pressed','true');b.textContent='暫停流程';function next(){if(document.body.classList.contains('motion-off')||location.hash!=='#solutions'){stop();return}if(at<3){stage(at+1);timer=setTimeout(next,1500)}else stop()}timer=setTimeout(next,1500)};p.querySelector('a').onclick=()=>{document.querySelector('#need').value=x.need;document.querySelector('#problem').value=x.title+' '+x.pain;};}
hub.querySelectorAll('[data-bottleneck]').forEach((b,i)=>{b.onclick=()=>render(i);b.onkeydown=e=>{let n;if(e.key==='ArrowRight')n=(i+1)%items.length;if(e.key==='ArrowLeft')n=(i+items.length-1)%items.length;if(e.key==='Home')n=0;if(e.key==='End')n=items.length-1;if(n!==undefined){e.preventDefault();render(n);hub.querySelector(`[data-bottleneck="${n}"]`).focus()}}});render(0);window.addEventListener('hashchange',stop);document.querySelector('.motion-toggle')?.addEventListener('click',stop);
// Complement the existing investment cards with a gated validation diagram.
const v=document.createElement('details');v.className='venture-gate';v.innerHTML=`<summary><span>${icon('flow')} 從投資機會，到可執行事業</span><span>展開決策流程 ＋</span></summary><div class="venture-gate-body"><div class="gate-row"><span>機會研究<small>客群・需求・競品</small></span><i>→</i><span>商業盡調<small>來源・假設・紅旗</small></span><i>→</i><span>財務試算<small>成本・現金流・情境</small></span></div><div class="gate-decision">關鍵假設有足夠證據？</div><div class="gate-branches"><div><b>有 → 小規模試點</b><p>預算上限 → 里程碑 → KPI 驗收</p></div><div><b>不足 → 補查或暫緩</b><p>列待確認事項，設定重新評估條件。</p></div></div><p class="gate-caption">試點達標，再評估擴張；偏離門檻，調整或停止。</p></div>`;document.querySelector('#venture .diligence-note').before(v);v.addEventListener('toggle',()=>{v.querySelector('summary>span:last-child').textContent=v.open?'收合決策流程 −':'展開決策流程 ＋'});
})();
